'use strict';
// TEST-ONLY stand-in for Socket.IO's Server: keeps an in-memory set of fake
// sockets with rooms so the real connection/event handlers can be driven
// directly. Production uses real socket.io from package.json.
class Server {
  constructor(httpServer, opts) { this.opts = opts; this.mw = []; this.sockets = new Set(); this.handlers = {}; }
  use(fn) { this.mw.push(fn); }
  on(ev, fn) { this.handlers[ev] = fn; }
  _match(names) { return [...this.sockets].filter((s) => names.some((n) => s.rooms.has(n))); }
  to(names) { names = [].concat(names); const self = this; return { emit(ev, d) { for (const s of self._match(names)) s.received.push([ev, d]); } }; }
  in(names) { names = [].concat(names); return { fetchSockets: async () => this._match(names) }; }
  async connect(headers) {
    const io = this;
    const s = {
      data: {}, request: { headers }, rooms: new Set(), received: [], handlers: {}, connected: true,
      join(r) { this.rooms.add(r); }, leave(r) { this.rooms.delete(r); },
      on(ev, fn) { this.handlers[ev] = fn; },
      emit(ev, d) { this.received.push([ev, d]); },
      to(r) { const me = this; return { emit(ev, d) { for (const o of io._match([r])) if (o !== me) o.received.push([ev, d]); } }; },
      disconnect() { this.connected = false; io.sockets.delete(this); this.handlers.disconnecting?.(); this.handlers.disconnect?.(); },
      call(ev, payload) { return new Promise((resolve) => this.handlers[ev](payload, resolve)); },
    };
    for (const fn of this.mw) {
      const err = await new Promise((resolve) => fn(s, resolve));
      if (err) return { error: err.message };
    }
    this.sockets.add(s);
    await this.handlers.connection(s);
    return s;
  }
}
module.exports = { Server };
